extra_css:
/* Kintsugi surfaces: panels are black raku glaze (soft crackle, a window sheen) and each carries one mended seam in gold along an
   edge; hover warms the gold and lifts the panel as if picked up to the light. Scoped to own surfaces only. */
html[data-atmo="kintsugi"] .card, html[data-atmo="kintsugi"] .panel, html[data-atmo="kintsugi"] .gx-card {
  background: linear-gradient(118deg, transparent 0 62%, rgba(226,178,92,.0) 62.3%, rgba(240,200,120,.55) 62.6%, rgba(160,110,40,.35) 63%, transparent 63.3%),
    radial-gradient(120% 70% at 20% 0%, rgba(255,240,220,.07), transparent 55%), linear-gradient(180deg, rgba(30,26,22,.88), rgba(10,9,8,.94));
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(255,240,220,.09), inset 0 0 0 1px rgba(226,178,92,.14), 0 18px 46px rgba(0,0,0,.7);
  transition: transform .5s cubic-bezier(.2,1,.3,1), box-shadow .5s; }
html[data-atmo="kintsugi"] .card:hover, html[data-atmo="kintsugi"] .gx-card:hover {
  transform: translateY(-3px); box-shadow: inset 0 1px 0 rgba(255,240,220,.14), inset 0 0 0 1px rgba(226,178,92,.4), 0 0 24px rgba(226,178,92,.12), 0 24px 56px rgba(0,0,0,.75); }
html[data-atmo="kintsugi"] h1, html[data-atmo="kintsugi"] h2 { background: linear-gradient(180deg, #ffe7b0, #d4a24c 55%, #8a6420); -webkit-background-clip: text; background-clip: text; color: transparent; }

